import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { loginUser } from '../api';

function Home({ onLogin }) {
  const navigate = useNavigate();
  const [loginRole, setLoginRole] = useState(null); // 'principal','hod','staff'
  const [showRegister, setShowRegister] = useState(false);
  const [form, setForm] = useState({ email: '', password: '' });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleLogin = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      const res = await loginUser({ ...form, role: loginRole });
      onLogin(res.data.user, res.data.token);
      navigate(`/${res.data.user.role}/dashboard`);
    } catch (err) {
      setError(err.response?.data?.message || 'Login failed');
    } finally {
      setLoading(false);
    }
  };

  const bgStyle = {
    minHeight: '100vh',
    backgroundImage: `url('https://upload.wikimedia.org/wikipedia/commons/thumb/1/17/Sir_M._Visvesvaraya_Institute_of_Technology%2C_Bangalore.jpg/1280px-Sir_M._Visvesvaraya_Institute_of_Technology%2C_Bangalore.jpg')`,
    backgroundSize: 'cover',
    backgroundPosition: 'center',
    position: 'relative',
    display: 'flex',
    flexDirection: 'column'
  };

  const overlayStyle = {
    position: 'absolute', inset: 0,
    background: 'rgba(255,255,255,0.75)'
  };

  return (
    <div style={bgStyle}>
      {/* SMVIT Header */}
      <header className="smvit-header" style={{ position: 'relative', zIndex: 2 }}>
        <div className="smvit-logo-area">
          <div className="smvit-logo">SMVIT</div>
          <div>
            <div className="smvit-title">SIR M. VISVESVARAYA INSTITUTE OF TECHNOLOGY</div>
            <div className="smvit-subtitle">Affiliated to VTU, Belagavi | Approved by AICTE, New Delhi / Govt. of Karnataka | Accredited by NAAC</div>
          </div>
        </div>
      </header>

      <div style={overlayStyle} />

      <div style={{ position: 'relative', zIndex: 2, flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', padding: '2rem' }}>

        {!loginRole && !showRegister && (
          <div style={{ textAlign: 'center', maxWidth: '600px' }}>
            <h1 style={{ fontSize: '2rem', color: '#2563eb', fontWeight: '700', marginBottom: '0.5rem' }}>
              Welcome to SMVIT Meeting Portal
            </h1>
            <p style={{ color: '#555', marginBottom: '2rem' }}>
              Schedule & Manage Meetings — Login or Register to Continue
            </p>

            <div style={{ display: 'flex', gap: '1rem', justifyContent: 'center', marginBottom: '2rem', flexWrap: 'wrap' }}>
              <button className="btn btn-primary" style={{ padding: '0.8rem 2rem', fontSize: '1rem' }} onClick={() => setLoginRole('principal')}>
                Principal Login
              </button>
              <button className="btn" style={{ padding: '0.8rem 2rem', fontSize: '1rem', background: '#374151', color: 'white' }} onClick={() => setLoginRole('hod')}>
                HOD Login
              </button>
              <button className="btn btn-teal" style={{ padding: '0.8rem 2rem', fontSize: '1rem' }} onClick={() => setLoginRole('staff')}>
                Staff Login
              </button>
            </div>

            <p style={{ color: '#555', marginBottom: '1rem' }}>
              Can't login? <span style={{ color: '#2563eb', fontWeight: '600', cursor: 'pointer' }} onClick={() => setShowRegister(true)}>Register here</span>
            </p>
            <div style={{ display: 'flex', gap: '1rem', justifyContent: 'center', flexWrap: 'wrap' }}>
              <button className="btn btn-outline" style={{ padding: '0.6rem 1.5rem' }} onClick={() => navigate('/register/hod')}>
                Register as HOD
              </button>
              <button className="btn btn-outline" style={{ padding: '0.6rem 1.5rem' }} onClick={() => navigate('/register/staff')}>
                Register as Staff
              </button>
            </div>
          </div>
        )}

        {loginRole && (
          <div style={{ background: 'white', padding: '2.5rem', borderRadius: '16px', width: '100%', maxWidth: '420px', boxShadow: '0 10px 40px rgba(0,0,0,0.15)' }}>
            <h2 style={{ textAlign: 'center', marginBottom: '1.5rem', color: '#1e3a5f', textTransform: 'capitalize' }}>
              {loginRole === 'principal' ? '🏛️ Principal' : loginRole === 'hod' ? '👔 HOD' : '👤 Staff'} Login
            </h2>
            <form onSubmit={handleLogin}>
              <div className="form-group">
                <label>Email Address</label>
                <input type="email" placeholder="your@email.com" value={form.email}
                  onChange={e => setForm({ ...form, email: e.target.value })} required />
              </div>
              <div className="form-group">
                <label>Password</label>
                <input type="password" placeholder="Enter password" value={form.password}
                  onChange={e => setForm({ ...form, password: e.target.value })} required />
              </div>
              {error && <div className="alert alert-error">{error}</div>}
              <button type="submit" className="btn btn-primary" disabled={loading} style={{ width: '100%', padding: '0.8rem' }}>
                {loading ? 'Signing in...' : 'Login'}
              </button>
            </form>
            <button onClick={() => { setLoginRole(null); setError(''); }} style={{ width: '100%', marginTop: '1rem', background: 'none', border: 'none', color: '#2563eb', cursor: 'pointer' }}>
              ← Back
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

export default Home;
